mapper.select:
SELECT DISTINCT v.embedding_model AS model, v.embedding_dimensions AS dimensions FROM document_versions v JOIN documents d ON d.active_version_id = v.id WHERE v.status = 'READY' AND d.knowledge_base_id IN
#{knowledgeBaseId}
ORDER BY v.embedding_model, v.embedding_dimensions

SELECT kb.id AS knowledge_base_id, kb.name AS knowledge_base_name, c.id AS chunk_id, c.document_id, c.version_id, d.name AS document_name, c.content, c.heading, c.line_start, c.line_end, 1 - (c.embedding <=> CAST(#{vector} AS vector)) AS similarity FROM document_chunks c JOIN documents d ON d.id = c.document_id AND d.active_version_id = c.version_id JOIN knowledge_bases kb ON kb.id = d.knowledge_base_id JOIN document_versions v ON v.id = c.version_id WHERE v.status = 'READY' AND v.embedding_model = #{model} AND v.embedding_dimensions = #{dimensions} AND d.knowledge_base_id IN
#{knowledgeBaseId}
ORDER BY c.embedding <=> CAST(#{vector} AS vector), c.id LIMIT #{limit}
